class Solution { public: string reorderSpaces(string text){int spaces=count(text.begin(),text.end(),' ');stringstream stream(text);vector<string> words;string word;while(stream>>word)words.push_back(word);int gap=words.size()==1?0:spaces/(words.size()-1),tail=spaces-gap*(words.size()-1);string answer;for(int i=0;i<(int)words.size();++i){if(i)answer+=string(gap,' ');answer+=words[i];}answer+=string(tail,' ');return answer;} };
